import struct,glob,os

def boxes(data,start=0,end=None):
    end=end or len(data); p=start
    while p+8<=end:
        size,typ=struct.unpack('>I4s',data[p:p+8]); typ=typ.decode('latin1')
        hdr=8
        if size==1:
            size=struct.unpack('>Q',data[p+8:p+16])[0]; hdr=16
        elif size==0: size=end-p
        yield typ,p,p+hdr,p+size
        if size<hdr: break
        p+=size

def find(data,start,end,path):
    for typ,s,h,e in boxes(data,start,end):
        if typ==path[0]:
            if len(path)==1: return s,h,e
            return find(data,h,e,path[1:])
    return None
for f in sorted(glob.glob('design/assets/video/*.mp4')):
    data=open(f,'rb').read()
