import { useAuth } from '../context/AuthContext.jsx'
import Icon from './Icon.jsx'
import { formatRuntime } from './HeroBillboard.jsx'

export default function TitleCard({ item, onOpen, top10Rank, showProgress = false, noPreview = false, className = '' }) {
  const { api } = useAuth()
  const navigate = useNavigate()
  const anchorRef = useRef(null)
  const previewRef = useRef(null)
  const openTimer = useRef(null)
  const closeTimer = useRef(null)
  const [preview, setPreview] = useState(null)
  const [inList, setInList] = useState(Boolean(item.in_my_list))
  const [listId, setListId] = useState(item.my_list_id || null)
  const [userRating, setUserRating] = useState(item.user_rating ?? null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => { setInList(Boolean(item.in_my_list)); setListId(item.my_list_id || null); setUserRating(item.user_rating ?? null) },
    [item.id, item.in_my_list, item.my_list_id, item.user_rating])

  useEffect(() => () => {
    clearTimeout(openTimer.current)
    clearTimeout(closeTimer.current)
  }, [])

  function positionPreview() {
    if (!anchorRef.current) return
    const rect = anchorRef.current.getBoundingClientRect()
    const width = Math.min(Math.max(rect.width * 1.42, 260), 390)
    let left = rect.left + rect.width / 2 - width / 2
    left = Math.max(12, Math.min(left, window.innerWidth - width - 12))
    let top = rect.top - 24
    const estimatedHeight = width * 0.56 + 190
    if (top + estimatedHeight > window.innerHeight - 16) top = Math.max(12, window.innerHeight - estimatedHeight - 16)
    setPreview({ left, top, width })
  }

  function scheduleOpen() {
    if (noPreview) return
    clearTimeout(closeTimer.current)
    clearTimeout(openTimer.current)
    openTimer.current = setTimeout(positionPreview, 320)
  }

  function scheduleClose() {
    clearTimeout(openTimer.current)
    closeTimer.current = setTimeout(() => setPreview(null), 140)
  }

  useEffect(() => {
    if (!preview) return
    const close = () => setPreview(null)
    window.addEventListener('scroll', close, true)
    window.addEventListener('resize', close)
    return () => {
      window.removeEventListener('scroll', close, true)
      window.removeEventListener('resize', close)
    }
  }, [preview])

  async function toggleList() {
    if (busy) return
    setBusy(true)
    setError('')
    try {
      if (inList) {
        if (listId) await api.delete(`/api/my-list/${listId}`)
        else await api.delete(`/api/my-list/${item.id}`)
        setInList(false)
        setListId(null)
      } else {
        const result = await api.post('/api/my-list', { title_id: item.id })
        setInList(true)
        setListId(result.item?.my_list_id || null)
      }
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }

  async function quickRate(value) {
    if (busy) return
    setBusy(true)
    setError('')
    try {
      const result = await api.post(`/api/titles/${item.id}/rating`, { value })
      setUserRating(result.item?.user_rating ?? value)
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }

  function play(event) {
    event?.stopPropagation()
    setPreview(null)
    navigate(`/watch/${item.id}`)
  }

  function expand(event) {
    event?.stopPropagation()
    setPreview(null)
    onOpen?.(item)
  }

  const actionButtons = (
    <>
      <button type="button" className="round-action play-action" onClick={play} aria-label={`Play ${item.name}`}><Icon name="play" size={20} /></button>
      <button type="button" className={`round-action ${inList ? 'selected' : ''}`} onClick={(event) => { event.stopPropagation(); toggleList() }} aria-label={inList ? 'Remove from My List' : 'Add to My List'} disabled={busy}>
        <Icon name={inList ? 'check' : 'plus'} size={20} />
      </button>
      <button type="button" className={`round-action ${userRating === 1 ? 'selected' : ''}`} onClick={(event) => { event.stopPropagation(); quickRate(1) }} aria-label="I like this" disabled={busy}>
        <Icon name="thumbs-up" size={19} />
      </button>
      <button type="button" className="round-action expand-action" onClick={expand} aria-label={`More information about ${item.name}`}><Icon name="chevron-down" size={20} /></button>
    </>
  )

  const card = (
    <div
      ref={anchorRef}
      className={`title-card ${top10Rank ? 'ranked-card' : ''} ${className}`}
      onMouseEnter={scheduleOpen}
      onMouseLeave={scheduleClose}
      onClick={() => onOpen?.(item)}
      role="button"
      tabIndex={0}
      onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') onOpen?.(item) }}
    >
      {top10Rank && <span className="rank-number" aria-hidden="true">{top10Rank}</span>}
      <div className="poster-wrap">
        <img src={item.poster || item.backdrop} alt={item.name} loading="lazy" />
        {item.top10_rank && <span className="top10-corner">TOP 10</span>}
        {inList && <span className="list-corner" title="In My List"><Icon name="check" size={14} /></span>}
        {showProgress && item.progress_percent != null && (
          <span className="card-progress"><span style={{ width: `${item.progress_percent}%` }} /></span>
        )}
        {!noPreview && (
          <div className="card-hover-shade">
            <span className="card-hover-title">{item.name}</span>
            <div className="card-hover-actions">{actionButtons}</div>
          </div>
        )}
      </div>
      {error && <span className="card-error">{error}</span>}
    </div>
  )

  const previewCard = preview ? createPortal(
    <div
      ref={previewRef}
      className="hover-preview"
      style={{ left: preview.left, top: preview.top, width: preview.width }}
      onMouseEnter={() => clearTimeout(closeTimer.current)}
      onMouseLeave={scheduleClose}
      onClick={() => onOpen?.(item)}
    >
      <div className="hover-preview-image" style={{ backgroundImage: `url(${item.backdrop || item.poster})` }}>
        <div className="hover-preview-top-fade" />
        <button type="button" className="hover-close" onClick={(event) => { event.stopPropagation(); setPreview(null) }} aria-label="Close preview"><Icon name="x" size={16} /></button>
        <div className="hover-preview-title">{item.name}</div>
      </div>
      <div className="hover-preview-body">
        <div className="hover-preview-actions">{actionButtons}</div>
        <div className="hover-preview-meta">
          <span className="match-score">{Math.round((item.rating || 0) * 10)}% Match</span>
          <span className="maturity-badge">{item.maturity_rating}</span>
          <span>{item.kind === 'series' ? `${item.seasons || 1} Seasons` : formatRuntime(item.duration)}</span>
        </div>
        <div className="hover-tags">{(item.genres || []).slice(0, 3).map((genre) => <span key={genre}>{genre}</span>)}</div>
      </div>
    </div>,
    document.body,
  ) : null

  return <>{card}{previewCard}</>
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { createPortal } from 'react-dom'
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom'
import { useAuth } from '../context/AuthContext.jsx'
import Icon from './Icon.jsx'
import RateDialog from './RateDialog.jsx'
import { formatRuntime } from './HeroBillboard.jsx'

function episodeRuntime(seconds) {
  const minutes = Math.max(1, Math.round(Number(seconds || 0) / 60))
  return `${minutes}m`
}

export default function TitleModal() {
  const [params] = useSearchParams()
  const location = useLocation()
  const navigate = useNavigate()
  const { api, token } = useAuth()
  const titleId = params.get('title')
  const [title, setTitle] = useState(null)
  const [episodes, setEpisodes] = useState([])
  const [season, setSeason] = useState(1)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [rateOpen, setRateOpen] = useState(false)
  const [busy, setBusy] = useState(false)

  const close = useCallback(() => {
    const next = new URLSearchParams(params)
    next.delete('title')
    const qs = next.toString()
    if (location.pathname.startsWith('/watch')) navigate('/browse')
    else navigate(`${location.pathname}${qs ? `?${qs}` : ''}`)
  }, [params, location.pathname, navigate])

  useEffect(() => {
    if (!titleId || !token) {
      setTitle(null)
      setEpisodes([])
      return
    }
    let cancelled = false
    setLoading(true)
    setError('')
    setTitle(null)
    Promise.all([
      api.get(`/api/titles/${titleId}`),
      api.get(`/api/titles/${titleId}/episodes`),
    ]).then(([titleResult, episodeResult]) => {
      if (cancelled) return
      setTitle(titleResult.item)
      const nextEpisodes = episodeResult.items || []
      setEpisodes(nextEpisodes)
      setSeason(nextEpisodes[0]?.season || 1)
    }).catch((err) => {
      if (!cancelled) setError(err.message)
    }).finally(() => {
      if (!cancelled) setLoading(false)
    })
    return () => { cancelled = true }
  }, [titleId, token, api])

  useEffect(() => {
    if (!titleId) return
    const previous = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    function onKey(event) {
      if (event.key === 'Escape') {
        if (rateOpen) setRateOpen(false)
        else close()
      }
    }
    document.addEventListener('keydown', onKey)
    return () => {
      document.body.style.overflow = previous
      document.removeEventListener('keydown', onKey)
    }
  }, [titleId, close, rateOpen])

  const seasons = useMemo(() => [...new Set(episodes.map((episode) => episode.season))].sort((a, b) => a - b), [episodes])
  const visibleEpisodes = episodes.filter((episode) => episode.season === season)

  if (!titleId || !token) return null
  if (!title && !loading && !error) return null

  async function toggleList() {
    if (!title || busy) return
    setBusy(true)
    try {
      if (title.in_my_list) {
        await api.delete(`/api/my-list/${title.my_list_id || title.id}`)
        setTitle({ ...title, in_my_list: false, my_list_id: null })
      } else {
        const result = await api.post('/api/my-list', { title_id: title.id })
        setTitle({ ...title, in_my_list: true, my_list_id: result.item?.my_list_id })
      }
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }

  async function quickRate(value) {
    if (!title || busy) return
    setBusy(true)
    try {
      const result = await api.post(`/api/titles/${title.id}/rating`, { value })
      setTitle({ ...title, user_rating: result.item?.user_rating ?? value })
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }

  function play() {
    if (!title) return
    const firstEpisode = episodes[0]
    navigate(`/watch/${title.id}${firstEpisode ? `?ep=${firstEpisode.id}` : ''}`)
  }

  function playEpisode(episode) {
    navigate(`/watch/${title.id}?ep=${episode.id}`)
  }

  return createPortal(
    <div className="title-modal-overlay" role="dialog" aria-modal="true" aria-label={title?.name || 'Title details'} onClick={(event) => { if (event.target === event.currentTarget) close() }}>
      <div className="title-modal">
        <button type="button" className="modal-close" onClick={close} aria-label="Close title details"><Icon name="x" size={24} /></button>
        {loading && <div className="modal-loading">Loading details…</div>}
        {error && <div className="modal-loading form-error">{error}</div>}
        {title && (
          <>
            <div className="modal-hero" style={{ backgroundImage: `url(${title.backdrop || title.poster})` }}>
              <div className="modal-hero-gradient" />
              <div className="modal-hero-content">
                <h1>{title.name}</h1>
                <div className="modal-actions">
                  <button type="button" className="btn btn-play" onClick={play}><Icon name="play" size={23} /> Play</button>
                  <button type="button" className={`round-action modal-round ${title.in_my_list ? 'selected' : ''}`} onClick={toggleList} aria-label={title.in_my_list ? 'Remove from My List' : 'Add to My List'} disabled={busy}>
                    <Icon name={title.in_my_list ? 'check' : 'plus'} size={22} />
                  </button>
                  <button type="button" className={`round-action modal-round ${title.user_rating === 1 ? 'selected' : ''}`} onClick={() => quickRate(1)} aria-label="I like this" disabled={busy}><Icon name="thumbs-up" size={21} /></button>
                  <button type="button" className={`round-action modal-round ${title.user_rating === -1 ? 'selected' : ''}`} onClick={() => quickRate(-1)} aria-label="Not for me" disabled={busy}><Icon name="thumbs-down" size={21} /></button>
                  <button type="button" className="rate-link" onClick={() => setRateOpen(true)}>Rate this title</button>
                </div>
              </div>
            </div>
            <div className="modal-detail-grid">
              <div className="modal-main">
                <div className="modal-meta">
                  <span className="match-score">{Math.round((title.rating || 0) * 10)}% Match</span>
                  <span>{title.year}</span>
                  <span className="maturity-badge">{title.maturity_rating}</span>
                  <span>{title.kind === 'series' ? `${title.seasons} Season${title.seasons === 1 ? '' : 's'}` : formatRuntime(title.duration)}</span>
                  <span className="hd-badge">HD</span>
                </div>
                <p className="modal-synopsis">{title.synopsis}</p>
              </div>
              <aside className="modal-aside">
                <p><span className="aside-label">Genres</span> {(title.genres || []).join(', ') || '—'}</p>
                <p><span className="aside-label">Original language</span> {title.language_name || title.language || '—'}</p>
                <p><span className="aside-label">Maturity rating</span> {title.maturity_rating}</p>
                <p><span className="aside-label">This title is</span> {title.kind === 'series' ? 'A TV series' : 'A film'}</p>
              </aside>
            </div>
            {title.kind === 'series' && episodes.length > 0 && (
              <section className="episodes-section">
                <div className="episodes-header">
                  <h2>Episodes</h2>
                  {seasons.length > 1 && (
                    <label className="season-select">
                      <span>Season</span>
                      <select value={season} onChange={(event) => setSeason(Number(event.target.value))} aria-label="Select season">
                        {seasons.map((value) => <option key={value} value={value}>Season {value}</option>)}
                      </select>
                    </label>
                  )}
                </div>
                <div className="episode-list">
                  {visibleEpisodes.map((episode, index) => (
                    <button type="button" className="episode-row" key={episode.id} onClick={() => playEpisode(episode)}>
                      <span className="episode-number">{index + 1}</span>
                      <img src={episode.thumbnail || title.backdrop} alt="" loading="lazy" />
                      <span className="episode-info">
                        <span className="episode-title-line"><strong>{episode.name}</strong><small>{episodeRuntime(episode.duration)}</small></span>
                        <span className="episode-synopsis">{episode.synopsis}</span>
                      </span>
                      <span className="episode-play"><Icon name="play" size={24} /></span>
                    </button>
                  ))}
                </div>
              </section>
            )}
            {title.kind !== 'series' && (
              <section className="about-section">
                <h2>About <span>{title.name}</span></h2>
                <p className="about-genres"><span className="aside-label">Genres</span> {(title.genres || []).join(', ') || '—'}</p>
                <p className="about-genres"><span className="aside-label">This film is</span> {title.genre || '—'}</p>
              </section>
            )}
          </>
        )}
      </div>
      {rateOpen && title && (
        <RateDialog
          title={title}
          currentValue={title.user_rating}
          onClose={() => setRateOpen(false)}
          onRated={(value) => setTitle({ ...title, user_rating: value })}
        />
      )}
    </div>,
    document.body,
  )
}

