  '/assets/posters/movie_1400837.jpg', '/assets/posters/movie_1468683.jpg', '/assets/posters/movie_1084244.jpg',
  '/assets/posters/movie_1212763.jpg', '/assets/posters/movie_1440050.jpg', '/assets/posters/movie_931285.jpg',
