  const { openTitle } = useTitleOverlay()
  const [items, setItems] = useState([])
  const [genre, setGenre] = useState(null)
  const [allGenres, setAllGenres] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
